                      "text": "双非学校，工程管理，有很多问题。我们专业40个人，前5个学期，综合成绩排第3，要是再加上一个学期的成绩，裸分应该是第2或第1，综合应该可以到第1，基本可以拿到推免的名额，过了六级但是飘过，没有什么竞赛论文，拿过两年国家励志，校级三好学生等。…",
