                      "text": "大年初一再一次破防。专升本就真得不配找工作吗 大中小厂，动不动就是不要专升本，考研又考不上，看到个帖子哈啰也卡专升本，我滴滴字节也是专升本没了。...悔恨交加，为什么高中不多考点分，为什么专科不直接就业，为什么专升本考上了还要干互联网不选择考公。大年初一彻底破防了",
